Feedback export to PDF


Code
feedback_to_pdf &lt;- function(df, title, filename) {

  df &lt;- df %&gt;%
    filter(!is.na(feedback), feedback != "") %&gt;%
    arrange(ID)

  comments &lt;- paste0(
    "&lt;section class='comment'&gt;",
    "&lt;div class='id'&gt;ID: ",
    htmltools::htmlEscape(as.character(df$ID)),
    "&lt;/div&gt;",
    "&lt;div class='text'&gt;",
    htmltools::htmlEscape(df$feedback),
    "&lt;/div&gt;",
    "&lt;/section&gt;"
  )

  html &lt;- paste0(
    "&lt;!DOCTYPE html&gt;
    &lt;html&gt;
    &lt;head&gt;
    &lt;meta charset='UTF-8'&gt;
    &lt;style&gt;
      @page {
        size: A4;
        margin: 18mm;
      }

      body {
        font-family: Arial, sans-serif;
        font-size: 11pt;
        line-height: 1.45;
        color: #222;
      }

      h1 {
        font-size: 18pt;
        margin-bottom: 20px;
      }

      .comment {
        padding: 10px 0 14px 0;
        border-bottom: 1px solid #cccccc;
        page-break-inside: avoid;
      }

      .id {
        font-weight: bold;
        margin-bottom: 5px;
      }

      .text {
        white-space: pre-wrap;
        overflow-wrap: anywhere;
      }
    &lt;/style&gt;
    &lt;/head&gt;

    &lt;body&gt;
      &lt;h1&gt;", htmltools::htmlEscape(title), "&lt;/h1&gt;",
      paste(comments, collapse = "\n"),
    "&lt;/body&gt;
    &lt;/html&gt;"
  )

  html_file &lt;- tempfile(fileext = ".html")
  writeLines(html, html_file, useBytes = TRUE)

  output_file &lt;- normalizePath(filename, mustWork = FALSE)

  pagedown::chrome_print(
    input = html_file,
    output = output_file
  )

  message("Saved to: ", output_file)
}




